  'bar-4': {"googlePlaceId":"ChIJZXAkQ-JawokRtcgV21QC948","lat":40.663292999999996,"lng":-73.98487399999999,"businessStatus":"CLOSED_PERMANENTLY","reviews":[{"text":"This is the best live, local music venue in the neighborhood. It's intimate and comfortable. This place is a regular location with friends. The beer is good and the food isn't bad (for bar fare)…","author":"Andrew “Jamoozy” Sabisch","rating":4},{"text":"Great local bar. Decent cheap drinks and live music. They have nachos at te bar- avoid like the plague. Instead go for pickle backs.","author":"Karen Pendleton Fiscina","rating":4},{"text":"Good bar with lived-in seating and a nice atmosphere. Not as good when there's an open mic night and you want to have a conversation with someone.","author":"Margarita Montimore","rating":3}]},
